def split_funcs(text):
    # crude: function boundaries at column-0 '{' preceded by ')' at col 0
    lines=text.split("\n")
    starts=[]
    for i,l in enumerate(lines):
        if l.startswith("{") and i>0 and re.search(r'\)\s*$', lines[i-1]):
            starts.append(i)
    funcs=[]
    for idx,s in enumerate(starts):
        e = starts[idx+1]-1 if idx+1<len(starts) else len(lines)-1
        # find next column-0 '}' after s
        for j in range(s+1,len(lines)):
            if lines[j].startswith("}"):
                e=j; break
        funcs.append((s,e))
    return lines, funcs
